import React, { useMemo } from "react";
import { AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig, random } from '../remotionShim';
import { evolvePath } from "@remotion/paths";
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();



export type NetworkGraphProps = Record<string, any>;

// Helper to draw curved connections that bow outwards from the canvas center
const getCurveOutward = (p1: { x: number; y: number }, p2: { x: number; y: number }, offsetScale: number, cx: number, cy: number) => {
  const mx = (p1.x + p2.x) / 2;
  const my = (p1.y + p2.y) / 2;
  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;
  const dist = Math.sqrt(dx * dx + dy * dy) || 1;
  
  let nx = -dy / dist;
  let ny = dx / dist;

  const cxDir = mx - cx;
  const cyDir = my - cy;

  // Ensure the normal vector points away from the center
  if (nx * cxDir + ny * cyDir < 0) {
    nx = -nx;
    ny = -ny;
  }

  const cpx = mx + nx * dist * offsetScale;
  const cpy = my + ny * dist * offsetScale;
  
  return `M ${p1.x} ${p1.y} Q ${cpx} ${cpy} ${p2.x} ${p2.y}`;
};

const ComponentName: React.FC<NetworkGraphProps> = ({
  backgroundColor = "#08121c",
  transparentBackground = false,
  nodeGlowColor = "#00e5ff",
  nodeCoreColor = "#ffffff",
  lineColor = "rgba(0, 229, 255, 0.6)",
  durationInSeconds = 10,
  texts = ["Contract", "BOQ Rev.2", "Invoice #47", "Site Report", "Drawing A3"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Central layout geometry - perfectly centered and safe within the screen
  const cx = width / 2;
  const cy = height / 2; 
  const radius = Math.min(width, height) * 0.22;

  // Calculate the 5 main central nodes forming a pentagram
  const mainNodes = useMemo(() => {
    // Standard angles for a 5-pointed star starting from top
    const angles = [
      -Math.PI / 2,                          // Top
      -Math.PI / 2 + (2 * Math.PI) / 5,      // Right
      -Math.PI / 2 + (4 * Math.PI) / 5,      // Bottom Right
      -Math.PI / 2 + (6 * Math.PI) / 5,      // Bottom Left
      -Math.PI / 2 + (8 * Math.PI) / 5       // Left
    ];

    return angles.map((angle, i) => ({
      x: cx + radius * Math.cos(angle),
      y: cy + radius * Math.sin(angle),
      angle,
      id: i,
    }));
  }, [cx, cy, radius]);

  // Generate interconnecting lines between main nodes (Outer perimeter + Inner star)
  const mainPathsStr = useMemo(() => {
    const paths: string[] = [];
    // Outer perimeter connections
    for (let i = 0; i < 5; i++) {
      paths.push(getCurveOutward(mainNodes[i], mainNodes[(i + 1) % 5], 0.15, cx, cy));
    }
    // Inner cross-star connections
    for (let i = 0; i < 5; i++) {
      paths.push(getCurveOutward(mainNodes[i], mainNodes[(i + 2) % 5], 0.08, cx, cy));
    }
    return paths;
  }, [mainNodes, cx, cy]);

  // Generate smaller peripheral nodes branching off the main nodes (safe distances to avoid going off screen)
  const peripherals = useMemo(() => {
    const list = [];
    for (let i = 0; i < 5; i++) {
      const node = mainNodes[i];
      // 5 to 7 branches per main node
      const numBranches = 5 + Math.floor(random(`count-${i}`) * 3); 
      
      for (let j = 0; j < numBranches; j++) {
        // Spread branches outwards around the node's central angle
        const angleOffset = (random(`angle-${i}-${j}`) - 0.5) * 1.5; 
        const angle = node.angle + angleOffset;
        
        // Slightly tighter randomize length of branches to guarantee they stay on screen
        const dist = radius * 0.3 + random(`dist-${i}-${j}`) * radius * 0.35;
        const endX = node.x + Math.cos(angle) * dist;
        const endY = node.y + Math.sin(angle) * dist;

        // Curve lines slightly left or right randomly
        const curveDir = random(`curve-${i}-${j}`) > 0.5 ? 0.15 : -0.15;
        const path = getCurveOutward(node, { x: endX, y: endY }, curveDir, cx, cy);

        list.push({
          x: endX,
          y: endY,
          path,
          isCyan: random(`color-${i}-${j}`) > 0.4,
          mainNodeIdx: i,
        });
      }
    }
    return list;
  }, [mainNodes, radius, cx, cy]);

  // Render main connecting lines
  const mainLines = mainPathsStr.map((path, i) => {
    const delay = i * 2 + 10;
    const progress = frame < delay ? 0 : interpolate(frame - delay, [0, 30], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    const evo = evolvePath(progress, path);
    
    return (
      <path
        key={`ml-${i}`}
        d={path}
        stroke={lineColor}
        strokeWidth={2 * s}
        fill="none"
        strokeDasharray={evo.strokeDasharray}
        strokeDashoffset={evo.strokeDashoffset}
        strokeLinecap="round"
        style={{ transition: "none" }}
      />
    );
  });

  // Render peripheral connecting lines
  const peripheralLines = peripherals.map((p, i) => {
    const delay = p.mainNodeIdx * 4 + 30; // Starts after main structure
    const progress = frame < delay ? 0 : interpolate(frame - delay, [0, 25], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    const evo = evolvePath(progress, p.path);
    
    return (
      <path
        key={`pl-${i}`}
        d={p.path}
        stroke={lineColor}
        strokeWidth={1.5 * s}
        fill="none"
        strokeDasharray={evo.strokeDasharray}
        strokeDashoffset={evo.strokeDashoffset}
        strokeLinecap="round"
        style={{ transition: "none" }}
      />
    );
  });

  // Render large central glowing nodes with continuous pulsation
  const mainNodeElements = mainNodes.map((node, i) => {
    const delay = i * 4;
    const scale = frame < delay ? 0 : spring({ frame: frame - delay, fps, config: { damping: 12, mass: 0.8 } });
    
    // Continuous dynamic pulsation all through the duration
    const pulse = 1 + Math.sin(frame * 0.06 + i * 1.2) * 0.08;
    const finalScale = scale * pulse;

    return (
      <div
        key={`mn-${i}`}
        style={{
          position: "absolute",
          left: node.x,
          top: node.y,
          width: 70 * s,
          height: 70 * s,
          borderRadius: "50%",
          backgroundColor: nodeCoreColor,
          transform: `translate(-50%, -50%) scale(${finalScale})`,
          boxShadow: `
            0 0 ${15 * s}px ${5 * s}px rgba(255, 255, 255, 0.9),
            0 0 ${40 * s}px ${15 * s}px ${nodeGlowColor},
            0 0 ${100 * s}px ${35 * s}px ${nodeGlowColor}99
          `,
          zIndex: 10,
          transition: "none"
        }}
      />
    );
  });

  // Render small peripheral destination nodes with continuous pulsation
  const peripheralNodeElements = peripherals.map((p, i) => {
    const delay = p.mainNodeIdx * 4 + 45; // Pop in as their line finishes
    const scale = frame < delay ? 0 : spring({ frame: frame - delay, fps, config: { damping: 10, mass: 0.5 } });
    const color = p.isCyan ? nodeGlowColor : nodeCoreColor;
    
    // Continuous dynamic pulsation all through the duration
    const pulse = 1 + Math.sin(frame * 0.12 + i * 0.5) * 0.12;
    const finalScale = scale * pulse;
    
    return (
      <div
        key={`pn-${i}`}
        style={{
          position: "absolute",
          left: p.x,
          top: p.y,
          width: 18 * s,
          height: 18 * s,
          borderRadius: "50%",
          backgroundColor: color,
          transform: `translate(-50%, -50%) scale(${finalScale})`,
          boxShadow: `0 0 ${15 * s}px ${4 * s}px ${color}dd`,
          zIndex: 8,
          transition: "none"
        }}
      />
    );
  });

  // Render text labels aligned under main nodes
  const textElements = mainNodes.map((node, i) => {
    const delay = i * 4 + 15;
    const opacity = frame < delay ? 0 : interpolate(frame - delay, [0, 20], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    const yOffset = frame < delay ? 20 * s : interpolate(frame - delay, [0, 20], [20 * s, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

    return (
      <div
        key={`txt-${i}`}
        style={{
          position: "absolute",
          left: node.x,
          top: node.y + 70 * s,
          transform: `translate(-50%, ${yOffset}px)`,
          color: "white",
          fontSize: 32 * s,
          fontWeight: 700,
          fontFamily: interFamily,
          opacity,
          whiteSpace: "nowrap",
          zIndex: 15,
          textShadow: `0 0 ${12 * s}px rgba(0, 0, 0, 0.8), 0 0 ${24 * s}px rgba(0, 0, 0, 0.6)`,
          transition: "none"
        }}
      >
        {texts[i] || ""}
      </div>
    );
  });

  // Continuous subtle breathing of entire line-glow system
  const linePulseOpacity = interpolate(
    Math.sin(frame * 0.05),
    [-1, 1],
    [0.7, 1]
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <svg width={width} height={height} style={{ position: "absolute", overflow: "visible" }}>
        <defs>
          <filter id="line-glow" x="-20%" y="-20%" width="140%" height="140%">
            <feGaussianBlur stdDeviation={4 * s} result="blur" />
            <feMerge>
              <feMergeNode in="blur" />
              <feMergeNode in="blur" />
              <feMergeNode in="SourceGraphic" />
            </feMerge>
          </filter>
        </defs>
        <g filter="url(#line-glow)" style={{ opacity: linePulseOpacity, transition: "none" }}>
          {mainLines}
          {peripheralLines}
        </g>
      </svg>
      {mainNodeElements}
      {peripheralNodeElements}
      {textElements}
    </AbsoluteFill>
  );
};

export default ComponentName;